import React, { useMemo, useRef, useState } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { Html, Line, OrbitControls, RoundedBox } from "@react-three/drei";
import * as THREE from "three";
import { Activity, Pause, Play } from "lucide-react";

type Status = "normal" | "attention" | "critical";
type Kind = "supply" | "medication" | "patient";
type Area = { id:string; name:string; pos:[number,number,number]; size:[number,number,number]; status:Status; stock:number; activity:number };
type Flow = { from:string; to:string; kind:Kind; volume:number };

const areas: Area[] = [
  {id:"central",name:"Central",pos:[-6,0,0],size:[3,1,2.4],status:"normal",stock:86,activity:12},
  {id:"farmacia",name:"Farmacia",pos:[-2,0,-3],size:[3,1,2.2],status:"attention",stock:57,activity:18},
  {id:"cirugia",name:"Cirugía",pos:[2,0,0],size:[3.2,1,2.6],status:"normal",stock:74,activity:21},
  {id:"q01",name:"Q01",pos:[6,0,-2.8],size:[2,1,1.6],status:"normal",stock:81,activity:5},
  {id:"q02",name:"Q02",pos:[6,0,0],size:[2,1,1.6],status:"critical",stock:29,activity:11},
  {id:"q03",name:"Q03",pos:[6,0,2.8],size:[2,1,1.6],status:"attention",stock:44,activity:7},
  {id:"hosp",name:"Hospitalización",pos:[-2,0,3.2],size:[3.2,1,2.2],status:"normal",stock:79,activity:14},
];
const flows: Flow[] = [
  {from:"central",to:"farmacia",kind:"supply",volume:28},
  {from:"central",to:"hosp",kind:"supply",volume:19},
  {from:"farmacia",to:"cirugia",kind:"medication",volume:17},
  {from:"cirugia",to:"q01",kind:"medication",volume:7},
  {from:"cirugia",to:"q02",kind:"medication",volume:12},
  {from:"cirugia",to:"q03",kind:"medication",volume:8},
  {from:"hosp",to:"cirugia",kind:"patient",volume:6},
];
const statusColor:Record<Status,string>={normal:"#006f7b",attention:"#ad7a00",critical:"#9d2f36"};
const flowColor:Record<Kind,string>={supply:"#7dd3fc",medication:"#f0b95c",patient:"#c4b5fd"};
const area=(id:string)=>areas.find(a=>a.id===id)!;

function FlowDot({flow,paused,index}:{flow:Flow;paused:boolean;index:number}) {
  const ref=useRef<THREE.Mesh>(null);
  const t=useRef((index*.31)%1);
  const a=area(flow.from).pos,b=area(flow.to).pos;
  const curve=useMemo(()=>new THREE.QuadraticBezierCurve3(
    new THREE.Vector3(a[0],.85,a[2]),
    new THREE.Vector3((a[0]+b[0])/2,1.7,(a[2]+b[2])/2),
    new THREE.Vector3(b[0],.85,b[2])
  ),[a,b]);
  useFrame((_,d)=>{if(paused||!ref.current)return;t.current=(t.current+d*(.08+flow.volume/500))%1;ref.current.position.copy(curve.getPoint(t.current));});
  return <mesh ref={ref}><sphereGeometry args={[.11,14,14]}/><meshStandardMaterial color={flowColor[flow.kind]} emissive={flowColor[flow.kind]} emissiveIntensity={.8}/></mesh>;
}

function Scene({selected,setSelected,kinds,paused}:{selected:string;setSelected:(id:string)=>void;kinds:Kind[];paused:boolean}) {
  return <>
    <color attach="background" args={["#09090b"]}/>
    <fog attach="fog" args={["#09090b",16,34]}/>
    <ambientLight intensity={.9}/><directionalLight position={[7,12,8]} intensity={1.6}/>
    <gridHelper args={[24,24,"#27272a","#18181b"]}/>
    {areas.map(a=><group key={a.id} position={[a.pos[0],a.size[1]/2,a.pos[2]]}>
      <RoundedBox args={a.size} radius={.15} smoothness={4} onClick={e=>{e.stopPropagation();setSelected(a.id)}}>
        <meshStandardMaterial color={statusColor[a.status]} emissive={statusColor[a.status]} emissiveIntensity={selected===a.id?.35:.08}/>
      </RoundedBox>
      <Html position={[0,1,0]} center distanceFactor={12}><button onClick={()=>setSelected(a.id)} className="rounded border border-white/10 bg-zinc-950/90 px-2 py-1 text-[10px] font-semibold text-white">{a.name}</button></Html>
    </group>)}
    {flows.filter(f=>kinds.includes(f.kind)).map(f=>{
      const p1=area(f.from).pos,p2=area(f.to).pos;
      return <React.Fragment key={`${f.from}-${f.to}`}>
        <Line points={[[p1[0],.85,p1[2]],[p2[0],.85,p2[2]]]} color={flowColor[f.kind]} transparent opacity={.22} lineWidth={1}/>
        {Array.from({length:Math.max(1,Math.min(3,Math.ceil(f.volume/10)))},(_,i)=><FlowDot key={i} flow={f} paused={paused} index={i}/>)}
      </React.Fragment>
    })}
    <OrbitControls makeDefault enableDamping minDistance={9} maxDistance={25} maxPolarAngle={Math.PI/2.05}/>
  </>;
}

export default function App(){
  const [selected,setSelected]=useState("q02");
  const [kinds,setKinds]=useState<Kind[]>(["supply","medication"]);
  const [paused,setPaused]=useState(false);
  const current=area(selected);
  const toggle=(k:Kind)=>setKinds(v=>v.includes(k)?(v.length===1?v:v.filter(x=>x!==k)):[...v,k]);
  const labels:Record<Kind,string>={supply:"Abastecimiento",medication:"Medicamentos",patient:"Pacientes"};
  return <div className="flex h-full w-full flex-col overflow-hidden bg-zinc-950 text-zinc-100">
    <header className="flex flex-wrap items-center justify-between gap-2 border-b border-zinc-800 px-3 py-2">
      <div><div className="flex items-center gap-2 text-sm font-semibold"><Activity className="h-4 w-4 text-cyan-400"/>Hospital Digital Twin · Abastecimiento</div><div className="text-[10px] text-zinc-500">MVP 3D · contrato listo para REST / WebSocket / MCP</div></div>
      <div className="flex gap-1">{(["supply","medication","patient"] as Kind[]).map(k=><button key={k} onClick={()=>toggle(k)} className={`rounded border px-2 py-1 text-[10px] ${kinds.includes(k)?"border-zinc-500 bg-zinc-700":"border-zinc-800 bg-zinc-900 text-zinc-500"}`}>{labels[k]}</button>)}<button onClick={()=>setPaused(v=>!v)} className="grid h-7 w-7 place-items-center rounded border border-zinc-700 bg-zinc-900">{paused?<Play className="h-3.5 w-3.5"/>:<Pause className="h-3.5 w-3.5"/>}</button></div>
    </header>
    <div className="grid min-h-0 flex-1 grid-cols-[minmax(0,1fr)_210px] max-[700px]:grid-cols-1">
      <div className="min-h-[260px]"><Canvas camera={{position:[13,11,14],fov:48}} dpr={[1,1.5]}><Scene selected={selected} setSelected={setSelected} kinds={kinds} paused={paused}/></Canvas></div>
      <aside className="border-l border-zinc-800 p-3 max-[700px]:border-l-0 max-[700px]:border-t">
        <div className="text-[9px] uppercase tracking-[.16em] text-zinc-500">Área seleccionada</div>
        <div className="mt-1 text-lg font-semibold">{current.name}</div>
        <div className="mt-3 grid grid-cols-2 gap-2">
          <Metric label="Stock sano" value={`${current.stock}%`}/><Metric label="Eventos" value={String(current.activity)}/>
        </div>
        <div className="mt-3 rounded border border-zinc-800 bg-zinc-900/60 p-2.5 text-[10px] leading-relaxed text-zinc-400">
          Estado: <strong style={{color:statusColor[current.status]}}>{current.status==="critical"?"CRÍTICO":current.status==="attention"?"ATENCIÓN":"NORMAL"}</strong><br/>
          Esta fase usa datos simulados. La siguiente sustituye el dataset por eventos reales sin acoplar la escena a las tablas clínicas.
        </div>
      </aside>
    </div>
  </div>
}
function Metric({label,value}:{label:string;value:string}){return <div className="rounded border border-zinc-800 bg-zinc-900/70 p-2"><div className="text-[9px] uppercase text-zinc-500">{label}</div><div className="mt-1 text-lg font-semibold tabular-nums">{value}</div></div>}
